1	// The "I just laughed" voice command runs through Apple's Speech framework,
2	// which streams audio to Apple's servers unless the request opts out — so every
3	// SFSpeechAudioBufferRecognitionRequest the app builds must set
4	// requiresOnDeviceRecognition (VoiceCommand.swift:48, "never leaves the Mac";
5	// DESIGN §3/§6, and the Info.plist usage string promises the same to the user).
6	// Dependency-free (a local pack loads without the canon mount): plain findings.
7	
8	const rule = {
9	  id: 'on-device-privacy/on-device-speech',
10	  severity: 'blocking',
11	  description: 'Every SFSpeech recognition request must set requiresOnDeviceRecognition',
12	  doc: '.claudinite/local/packs/on-device-privacy/RULES.md',
13	  why: "Speech defaults to server-side recognition, which would ship living-room audio to Apple — the opposite of what the app's mic prompt promises",
14	
15	  run(ctx) {
16	    const out = [];
17	    for (const file of ctx.files.filter((f) => f.startsWith('mac/Sources/') && f.endsWith('.swift'))) {
18	      const text = ctx.read(file);
19	      if (text === null) continue;
20	      const lines = text.split('\n');
21	      for (let i = 0; i < lines.length; i += 1) {
22	        if (!/\bSFSpeechAudioBufferRecognitionRequest\s*\(/.test(lines[i])) continue;
23	        // The opt-out is set on the fresh request, near its construction — look
24	        // ahead a short window rather than requiring an exact line.
25	        const window = lines.slice(i, i + 12).join('\n');
26	        if (/requiresOnDeviceRecognition\s*=\s*true/.test(window)) continue;
27	        out.push({
28	          rule: rule.id,
29	          severity: rule.severity,
30	          file,
31	          line: i + 1,
32	          what: 'a speech recognition request is built without requiresOnDeviceRecognition = true',
33	          why: rule.why,
34	          fix: 'set requiresOnDeviceRecognition = true on the request right after constructing it',
35	          doc: rule.doc,
36	        });
37	      }
38	    }
39	    return out;
40	  },
41	};
42	
43	export default rule;
